export type TimerFont = 'blocky' | 'digital' | 'pixel' | 'gradient';

export const FONTS: TimerFont[] = ['blocky', 'digital', 'pixel', 'gradient'];

// ---------- timer colors (pastels, flat fill — no gradient) ----------

export type TimerColor = 'gray' | 'pink' | 'peach' | 'lemon' | 'mint' | 'sky' | 'lilac';

export const TIMER_COLORS: TimerColor[] = ['gray', 'pink', 'peach', 'lemon', 'mint', 'sky', 'lilac'];

export const TIMER_COLOR_HEX: Record<Exclude<TimerColor, 'gray'>, string> = {
  pink: '#FFB3C6',
  peach: '#FFD1A9',
  lemon: '#FDFD96',
  mint: '#B5EAD7',
  sky: '#A7C7E7',
  lilac: '#C3B1E1',
};

function TimerGlyphs({ active, font, color }: { active: Active | null; font: TimerFont; color: TimerColor }) {
  const rows = timerRows(active ? elapsedSeconds(active) : 0, font);
  const glyphColor = font === 'blocky' && color !== 'gray' ? TIMER_COLOR_HEX[color] : active ? 'green' : 'gray';
  return (
    <>
      {rows.map((row, index) =>
        font === 'gradient' ? (
          <GradientText key={index} row={row} />
        ) : (
          <Text key={index} color={glyphColor} bold>{row}</Text>
        ),
      )}
    </>
  );
}

